const html = $input.first().json.data;

function cleanNumber(str) {
  return parseFloat(
    String(str || '')
      .replace(/<[^>]+>/g, '')
      .replace(/₹|,/g, '')
      .trim()
  );
}

function getRate(label) {
  const re = new RegExp(
    label + String.raw`[\s\S]*?₹\s*([0-9,]+(?:\.[0-9]+)?)`,
    'i'
  );

  const m = html.match(re);
  if (!m) throw new Error(`Could not find rate for ${label}`);

  const value = cleanNumber(m[1]);
  if (isNaN(value)) {
    throw new Error(`Invalid numeric value for ${label}: ${m[1]}`);
  }

  return value;
}

function getLastUpdated() {
  const m = html.match(
    /Last updated Time\s*:\s*<span[^>]*class=["'][^"']*updated-time[^"']*["'][^>]*>([\s\S]*?)<\/span>/i
  );

  if (m) {
    return m[1].replace(/<[^>]+>/g, '').trim();
  }

  const fallback = html.match(/Last updated Time\s*[-:]?\s*([\d/]+\s+\d{1,2}:\d{2}\s+[AP]M)/i);
  if (fallback) return fallback[1].trim();

  throw new Error('Could not find last updated timestamp');
}

function parseIndianDt(str) {
  const m = str.match(/(\d{2})\/(\d{2})\/(\d{2})\s+(\d{1,2}):(\d{2})\s+(AM|PM)/i);
  if (!m) return str;

  let [, dd, mo, yy, hh, mm, ampm] = m;
  hh = parseInt(hh, 10);

  if (ampm.toUpperCase() === 'PM' && hh !== 12) hh += 12;
  if (ampm.toUpperCase() === 'AM' && hh === 12) hh = 0;

  return `20${yy}-${mo}-${dd}T${String(hh).padStart(2, '0')}:${mm}:00`;
}

const lastUpdatedRaw = getLastUpdated();

const g_price_22k = getRate('GOLD RATE 22k');
const g_price_24k = getRate('GOLD RATE 24k');
const g_price_18k = getRate('GOLD RATE 18k');
const silver_price = getRate('SILVER RATE');

const now = new Date();
const edw_publn_id = now.toISOString().slice(0, 16).replace('T', ' ');

return [
  {
    json: {
      web_last_updated_ts: parseIndianDt(lastUpdatedRaw),
      g_price_18k_gram: g_price_18k,
      g_price_22k_gram: g_price_22k,
      g_price_24k_gram: g_price_24k,
      silver_price_gram: silver_price,
      edw_publn_id
    }
  }
];

// Validate all required fields are present and numeric
const d = $input.first().json;
const required = ['web_last_updated_ts','g_price_18k_gram','g_price_22k_gram','g_price_24k_gram','silver_price_gram','edw_publn_id'];

for (const field of required) {
  if (d[field] === undefined || d[field] === null || d[field] === '') {
    throw new Error(`Validation failed: missing field "${field}"`);
  }
}

const numericFields = ['g_price_18k_gram','g_price_22k_gram','g_price_24k_gram','silver_price_gram'];
for (const field of numericFields) {
  if (isNaN(d[field])) {
    throw new Error(`Validation failed: "${field}" is not a number → value: ${d[field]}`);
  }
  if (d[field] <= 0) {
    throw new Error(`Validation failed: "${field}" must be > 0 → value: ${d[field]}`);
  }
}

return $input.all();
